import assert from 'node:assert/strict';
import fs from 'node:fs';
import vm from 'node:vm';
const scope={window:{}};vm.runInNewContext(fs.readFileSync('js/nagweb-story-model.js','utf8'),scope);const model=scope.window.NAGWEB_STREAM_MODEL,plain=x=>JSON.parse(JSON.stringify(x)),c=model.config({kind:'ticker-loop',backgroundType:'none'});
assert.equal(c.zoom,45);assert.equal(c.angle,-6);assert.equal(c.movement,'continuous');assert.equal(c.orientation,'horizontal');assert.equal(c.direction,'opposed');assert.equal(c.pulseCount,3);assert.equal(c.zoomPulseAmount,25);assert.equal(c.stops,5);assert.equal(c.waypointZoom,1.8);assert.equal(c.creepSpeed,15);assert.equal(c.pause,35);assert.equal(c.cardRatio,'1:1');assert.equal(c.backgroundType,'none');
for(const [width,height] of [[1280,720],[390,844]])for(const count of [4,12,24])for(const orientation of ['horizontal','vertical'])for(const movement of ['continuous','zoomPulse','zoomWaypoints']){
 const cfg={...c,orientation,movement,frameRatio:'auto'},layout=p=>model.layout(width,height,cfg,p,count),first=layout(0);assert.equal(first.length,count);assert.deepEqual(plain(first),plain(layout(1)),'Complete cycles close exactly');const seen=Array(count).fill(false);
 for(let phase=0;phase<120;phase++)for(const card of layout(phase/120)){
  seen[card.slot]||=card.visible;assert.equal(card.instances.length>0,card.visible);assert.ok(card.width<=width+.001&&card.height<=height+.001);assert.equal(card.textureWidth,first[card.slot].textureWidth,'Zoom uses a stable source texture');assert.equal(card.textureHeight,first[card.slot].textureHeight);assert.equal(card.corner,first[card.slot].corner);
  for(const t of card.instances){assert.equal(t.upper.length,2);assert.equal(t.lower.length,2);const [a,b,d,e]=t.polygon,u={x:b.x-a.x,y:b.y-a.y},v={x:e.x-a.x,y:e.y-a.y};assert.ok(Math.abs(u.x*v.x+u.y*v.y)<1e-6,'Rotating the plane preserves rectangular cards');for(const p of t.polygon)assert.ok(Number.isFinite(p.x)&&Number.isFinite(p.y));assert.ok(Math.abs(d.x-(b.x+e.x-a.x))<1e-7&&Math.abs(d.y-(b.y+e.y-a.y))<1e-7);}
 }
 assert.ok(seen.every(Boolean),'Every image crosses the visible frame');
 const a=layout(.21),b=model.layout(width*2,height*2,cfg,.21,count);for(let i=0;i<count;i++){assert.equal(a[i].instances.length,b[i].instances.length);for(let j=0;j<a[i].instances.length;j++)for(let k=0;k<4;k++)for(const axis of ['x','y'])assert.ok(Math.abs(a[i].instances[j].polygon[k][axis]*2-b[i].instances[j].polygon[k][axis])<1e-7,'Scaling preserves the arrangement');}
}
for(const orientation of ['horizontal','vertical']){
 const cfg={...c,angle:0,frameRatio:'auto',orientation},a=model.layout(1000,600,cfg,.1,4),b=model.layout(1000,600,cfg,.105,4),axis=orientation==='horizontal'?'x':'y',fixed=orientation==='horizontal'?'y':'x';let checked=0;
 for(const card of a)for(const tile of card.instances){const next=b[card.slot].instances.filter(t=>t.row===tile.row).sort((u,v)=>Math.abs(u.polygon[0][axis]-tile.polygon[0][axis])-Math.abs(v.polygon[0][axis]-tile.polygon[0][axis]))[0];if(!next)continue;const delta=next.polygon[0][axis]-tile.polygon[0][axis];if(Math.abs(delta)>100)continue;assert.ok(tile.row%2?delta>0:delta<0);assert.equal(next.polygon[0][fixed],tile.polygon[0][fixed]);checked++;}assert.ok(checked>2);
}
const pose=(cfg,p)=>plain(model.layout(1280,720,cfg,p,12));assert.notDeepEqual(pose({...c,direction:'same'},.21),pose(c,.21));assert.notDeepEqual(pose({...c,movement:'zoomPulse'},.21),pose(c,.21));assert.notDeepEqual(pose({...c,movement:'zoomWaypoints'},.21),pose(c,.21));assert.notDeepEqual(pose({...c,orientation:'vertical'},.21),pose(c,.21));
const zoom={...c,movement:'zoomWaypoints',creepSpeed:0,pause:70};assert.deepEqual(pose(zoom,.005),pose(zoom,.015),'With no creep a camera stop holds the scene');assert.notDeepEqual(pose({...zoom,creepSpeed:50},.005),pose({...zoom,creepSpeed:50},.015));assert.equal(model.layout(1280,720,zoom,0,12)[0].cameraScale,1.8);assert.equal(model.layout(1280,720,zoom,.1,12)[0].cameraScale,1);
const sequence={...c,movement:'zoomPulse',turns:3,start:20,end:80};assert.equal(model.phase(.1,sequence,true),0);assert.equal(model.phase(.5,sequence,true),1.5);assert.equal(model.phase(.9,sequence,true),3);assert.deepEqual(plain(model.layout(1280,720,sequence,.1,12,1,true)),plain(model.layout(1280,720,sequence,.9,12,1,true)));
assert.equal(model.config({kind:'ticker-loop',angle:-1000}).angle,-15);assert.equal(model.config({kind:'ticker-loop',zoom:1000}).zoom,70);assert.equal(model.config({kind:'ticker-loop',waypointZoom:1000}).waypointZoom,3);assert.equal(model.config({kind:'ticker-loop',movement:'invalid',direction:'invalid',orientation:'invalid'}).movement,'continuous');assert.equal(model.layout(1280,720,c,0,100).length,24);
const serialized=vm.runInNewContext('('+scope.window.NAGWEB_CREATE_STREAM_MODEL.toString()+')()');assert.deepEqual(plain(serialized.layout(1280,720,{...sequence,movement:'zoomWaypoints',orientation:'vertical'},.32,24,1,true)),plain(model.layout(1280,720,{...sequence,movement:'zoomWaypoints',orientation:'vertical'},.32,24,1,true)));
console.log('Ticker Loop: 4–24 imágenes, filas/columnas, rotación sin deformar, pulsos/paradas de cámara/pausa y avance lento, texturas estables, cierre exacto, escala proporcional, Scroll y fábrica exportada OK');
